import { Actor, log } from 'apify';

// Pure helpers (no network) so they can be unit-tested offline.

function parseCount(s) {
    if (s == null) return null;
    const m = String(s).match(/(\d[\d.,\s\xa0]*)(?:\s*(k|m|b|mil|mill(?:ones)?|mln)(?![a-záéíóú]))?/i);
    if (!m) return null;
    const raw = m[1].trim().replace(/[\s\xa0]/g, '');
    const suf = m[2]?.toLowerCase();
    const mult = !suf ? 1 : suf === 'k' || suf === 'mil' ? 1e3 : suf === 'b' ? 1e9 : 1e6;
    // With a suffix the number may have decimals (1.5K, 8,32 K); without one it is a whole count (10.589 / 1,234).
    const n = suf ? parseFloat(raw.replace(/[.,](?=\d{3}(\D|$))(?=.*[.,])/g, '').replace(',', '.')) : parseInt(raw.replace(/[.,]/g, ''), 10);
    return Number.isNaN(n) ? null : Math.round(n * mult);
}

function decodeHtml(s) {
    if (s == null) return null;
    return s
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/g, ' ')
        .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'")
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
        .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
        .trim();
}

// Telegram names that are site sections, not channels.
const TG_RESERVED = new Set(['s', 'share', 'joinchat', 'addstickers', 'addemoji', 'proxy', 'socks', 'iv', 'login', 'setlanguage', 'addtheme', 'bg', 'c', 'boost', 'contact', 'k', 'z', 'a', 'apps', 'blog', 'faq', 'privacy', 'tos', 'api', 'dl', 'js', 'css', 'img', 'invoice', 'giftcode', 'nft', 'addlist']);

/**
 * Finds community links (Telegram, Discord, WhatsApp groups) in any text or HTML.
 * Also unwraps YouTube redirect links (youtube.com/redirect?q=...).
 * Returns [{ platform, key, url }], de-duplicated.
 */
function extractCommunityLinks(raw) {
    if (!raw) return [];
    let text = String(raw)
        .replace(/\x5cu0026/g, '&').replace(/\x5cu003d/gi, '=').replace(/\\\//g, '/').replace(/&amp;/g, '&');
    const unwrapped = [];
    for (const m of text.matchAll(/youtube\.com\/redirect\?[^"'\s<>]*?[?&]q=([^&"'\s<>]+)/g)) {
        try { unwrapped.push(decodeURIComponent(m[1])); } catch { /* ignore bad escapes */ }
    }
    text += `\n${unwrapped.join('\n')}`;
    const out = new Map();
    const add = (platform, key, url) => { const id = `${platform}:${key.toLowerCase()}`; if (!out.has(id)) out.set(id, { platform, key, url }); };

    for (const m of text.matchAll(/(?:https?:\/\/)?(?:www\.)?(?:t|telegram)\.(?:me|dog)\/(\+[\w-]{8,}|joinchat\/[\w-]{8,}|s\/[a-zA-Z][\w]{3,31}|[a-zA-Z][\w]{3,31})(?![\w])/g)) {
        let name = m[1];
        if (name.startsWith('+') || name.startsWith('joinchat/')) {
            const code = name.replace(/^joinchat\//, '+');
            add('telegram-private', code, `https://t.me/${code}`);
            continue;
        }
        name = name.replace(/^s\//, '');
        if (TG_RESERVED.has(name.toLowerCase())) continue;
        if (/bot$/i.test(name)) continue; // bots are not communities
        add('telegram', name, `https://t.me/${name}`);
    }
    for (const m of text.matchAll(/(?:https?:\/\/)?(?:www\.)?(?:discord\.gg|discord(?:app)?\.com\/invite)\/([a-zA-Z0-9-]{2,32})(?![\w-])/g)) {
        add('discord', m[1], `https://discord.gg/${m[1]}`);
    }
    for (const m of text.matchAll(/(?:https?:\/\/)?chat\.whatsapp\.com\/(?:invite\/)?([a-zA-Z0-9]{15,30})/g)) {
        add('whatsapp', m[1], `https://chat.whatsapp.com/${m[1]}`);
    }
    for (const m of text.matchAll(/(?:https?:\/\/)?(?:www\.)?whatsapp\.com\/channel\/([a-zA-Z0-9]{15,40})/g)) {
        add('whatsapp-channel', m[1], `https://whatsapp.com/channel/${m[1]}`);
    }
    return [...out.values()];
}

/**
 * Parses a public Telegram preview page (https://t.me/s/<name>) or the plain
 * page (https://t.me/<name>). Returns null for people and bots: only channels
 * and groups (things with subscribers/members) are communities.
 */
function parseTelegramPage(html, now = Date.now()) {
    if (!html) return null;
    const pick = (re) => html.match(re)?.[1] ?? null;
    const preview = /tgme_channel_info/.test(html);
    let title; let description; let members = null; let kind = null; let online = null;
    if (preview) {
        title = decodeHtml(pick(/class="tgme_channel_info_header_title"[^>]*>([\s\S]*?)<\/div>/));
        description = decodeHtml(pick(/class="tgme_channel_info_description"[^>]*>([\s\S]*?)<\/div>/));
        for (const m of html.matchAll(/class="counter_value">([^<]+)<\/span>\s*<span class="counter_type">([^<]+)</g)) {
            const type = m[2].trim().toLowerCase();
            if (/subscriber|member/.test(type)) { members = parseCount(m[1]); kind = /member/.test(type) ? 'group' : 'channel'; }
        }
    } else {
        title = decodeHtml(pick(/class="tgme_page_title"[^>]*>([\s\S]*?)<\/div>/));
        description = decodeHtml(pick(/class="tgme_page_description[^"]*"[^>]*>([\s\S]*?)<\/div>/));
        const extra = decodeHtml(pick(/class="tgme_page_extra"[^>]*>([\s\S]*?)<\/div>/)) ?? '';
        const sub = extra.match(/([\d\s\xa0.,KM]+)\s*(subscribers?|members?)/i);
        if (sub) { members = parseCount(sub[1]); kind = /member/i.test(sub[2]) ? 'group' : 'channel'; }
        const on = extra.match(/([\d\s\xa0.,KM]+)\s*online/i);
        if (on) online = parseCount(on[1]);
    }
    if (members == null || !title) return null; // a person, a bot, or nothing
    const times = [...html.matchAll(/<time[^>]*datetime="([^"]+)"/g)].map((m) => Date.parse(m[1])).filter((t) => !Number.isNaN(t)).sort((a, b) => b - a);
    const last = times[0] ?? null;
    let postsPerWeek = null;
    if (times.length >= 2) {
        const spanDays = Math.max((times[0] - times.at(-1)) / 864e5, 1);
        postsPerWeek = Math.round(((times.length - 1) / spanDays) * 7 * 10) / 10;
    }
    // Other channels this one forwards from or links to (for discovery).
    const related = new Set();
    for (const m of html.matchAll(/tgme_widget_message_forwarded_from_name"\s+href="https?:\/\/t\.me\/([a-zA-Z][\w]{3,31})/g)) related.add(m[1]);
    const postsHtml = html.split('tgme_widget_message_wrap').slice(1).join(' ');
    for (const l of extractCommunityLinks(postsHtml)) if (l.platform === 'telegram') related.add(l.key);
    return {
        kind,
        title,
        description,
        members,
        online,
        lastPostAt: last ? new Date(last).toISOString() : null,
        daysSinceLastPost: last ? Math.floor((now - last) / 864e5) : null,
        postsPerWeek,
        related: [...related],
    };
}

function parseDiscordInvite(json) {
    if (!json?.guild) return null;
    return {
        title: json.guild.name ?? null,
        description: json.guild.description ?? json.profile?.description ?? null,
        members: json.approximate_member_count ?? json.profile?.member_count ?? null,
        online: json.approximate_presence_count ?? json.profile?.online_count ?? null,
    };
}

const LANG_WORDS = {
    es: ['de', 'la', 'que', 'el', 'en', 'los', 'para', 'con', 'una', 'señales', 'gratis', 'canal', 'grupo', 'aprende', 'cómo', 'operar', 'cuenta', 'mercado', 'también', 'más', 'nuestro'],
    en: ['the', 'and', 'to', 'of', 'for', 'with', 'you', 'your', 'free', 'signals', 'channel', 'join', 'learn', 'how', 'trade', 'account', 'market', 'our', 'daily', 'best'],
    pt: ['de', 'que', 'não', 'para', 'com', 'uma', 'você', 'sinais', 'grátis', 'canal', 'grupo', 'aprenda', 'como', 'operar', 'conta', 'mercado', 'nosso', 'também', 'mais', 'são'],
};
function detectLanguage(text) {
    if (!text) return null;
    const words = text.toLowerCase().match(/[a-záéíóúñãõçâêô]+/g) ?? [];
    if (words.length < 3) return null;
    const scores = {};
    for (const [lang, list] of Object.entries(LANG_WORDS)) {
        const set = new Set(list);
        scores[lang] = words.filter((w) => set.has(w)).length;
    }
    if (/[ãõç]|não|você/.test(text)) scores.pt += 2;
    if (/[ñ¿¡]/.test(text)) scores.es += 2;
    const best = Object.entries(scores).sort((a, b) => b[1] - a[1])[0];
    return best[1] >= 2 ? best[0] : null;
}

function relevance(text, terms) {
    if (!text || !terms?.length) return { score: 0, matched: [] };
    const t = text.toLowerCase();
    const matched = terms.filter((term) => {
        const k = term.toLowerCase().trim();
        if (!k) return false;
        if (k.length <= 4) return new RegExp(`(^|[^a-z0-9])${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^a-z0-9]|$)`).test(t);
        return t.includes(k);
    });
    return { score: matched.length, matched };
}

/** 0-100 ranking: audience size, activity and topic match. */
function scoreCommunity(c) {
    const size = Math.min(Math.log10((c.members ?? 0) + 1) / 6, 1) * 55; // 1M+ = full
    let activity = 0;
    if (c.postsPerWeek != null) activity = Math.min(c.postsPerWeek / 14, 1) * 20;
    else if (c.online != null && c.members) activity = Math.min((c.online / c.members) / 0.1, 1) * 20;
    else if (c.platform === 'youtube' && c.activeRecently) activity = 15;
    let fresh = 10;
    if (c.daysSinceLastPost != null) fresh = c.daysSinceLastPost <= 7 ? 10 : c.daysSinceLastPost <= 30 ? 5 : 0;
    const topic = Math.min((c.matchedTerms?.length ?? 0) / 3, 1) * 15;
    return Math.round(size + activity + fresh + topic);
}

// ---------------- Actor ----------------

await Actor.init();

const DEFAULT_KEYWORDS = ['forex signals', 'señales forex', 'xauusd gold trading', 'prop firm challenge', 'cuenta de fondeo trading', 'expert advisor mt5'];
const DEFAULT_TERMS = ['forex', 'trading', 'trader', 'traders', 'xauusd', 'gold', 'oro', 'señales', 'signals', 'sinais', 'prop firm', 'fondeo', 'funded', 'mt4', 'mt5', 'metatrader', 'scalping', 'swing', 'futures', 'futuros', 'nasdaq', 'us30', 'indices', 'índices', 'expert advisor', 'robot', 'bot', 'pips', 'smc', 'ict', 'price action', 'crypto', 'cripto', 'bitcoin', 'opciones', 'options', 'bolsa', 'stocks', 'acciones', 'day trading', 'broker'];

const input = (await Actor.getInput()) ?? {};
const clean = (a) => (a ?? []).map((s) => String(typeof s === 'string' ? s : s?.url ?? '').trim()).filter(Boolean);
const keywords = clean(input.keywords).length ? clean(input.keywords) : (input.keywords ? [] : DEFAULT_KEYWORDS);
const terms = clean(input.nicheTerms).length ? clean(input.nicheTerms) : DEFAULT_TERMS;
const seeds = clean(input.telegramChannels);
const {
    language = 'en',
    country = 'US',
    maxChannelsPerKeyword = 10,
    videosToScanPerKeyword = 5,
    telegramDepth = 1,
    maxTelegramChannels = 80,
    minMembers = 500,
    maxDaysSinceLastPost = 60,
    languages = [],
    includeYouTubeChannels = true,
    includeUnknownSize = true,
    includeUnrelated = false,
    maxResults = 200,
    maxConcurrency = 4,
} = input;
if (!keywords.length && !seeds.length) throw new Error('Add at least one keyword or one Telegram channel.');

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const stats = { youtubeSearches: 0, youtubeChannelsScanned: 0, videosScanned: 0, telegramChecked: 0, discordChecked: 0, whatsappChecked: 0, skippedSmall: 0, skippedInactive: 0, skippedUnrelated: 0, skippedLanguage: 0, skippedNotCommunity: 0, errors: 0 };

async function request(url, { json = false, headers = {} } = {}) {
    let last;
    for (let i = 0; i < 3; i++) {
        try {
            const res = await fetch(url, { headers: { 'user-agent': UA, 'accept-language': `${language},en;q=0.8`, ...headers }, signal: AbortSignal.timeout(30000), redirect: 'follow' });
            if (res.status === 404 || res.status === 400 || res.status === 403) return null;
            if (res.status === 429 || res.status >= 500) throw new Error(`HTTP ${res.status}`);
            return json ? await res.json() : await res.text();
        } catch (e) { last = e; await sleep(1500 * (i + 1) + Math.random() * 800); }
    }
    stats.errors++;
    log.warning(`Request failed ${url}: ${last?.message}`);
    return null;
}

async function pool(items, worker) {
    let i = 0;
    const n = Math.max(1, Math.min(maxConcurrency, 8));
    await Promise.all(Array.from({ length: n }, async () => {
        while (i < items.length) { const it = items[i++]; try { await worker(it); } catch (e) { stats.errors++; log.warning(`${e.message}`); } }
    }));
}

// ---------- YouTube ----------
function grab(html, marker) {
    const i = html.indexOf(marker);
    if (i < 0) return null;
    const s = html.indexOf('{', i);
    let depth = 0;
    for (let j = s; j < html.length; j++) {
        const c = html[j];
        if (c === '"') { j++; while (j < html.length && html[j] !== '"') { if (html[j] === '\\') j++; j++; } continue; }
        if (c === '{') depth++;
        else if (c === '}') { depth--; if (depth === 0) { try { return JSON.parse(html.slice(s, j + 1)); } catch { return null; } } }
    }
    return null;
}
function findAll(o, key, out = []) {
    if (!o || typeof o !== 'object') return out;
    if (Array.isArray(o)) { for (const v of o) findAll(v, key, out); return out; }
    for (const [k, v] of Object.entries(o)) { if (k === key) out.push(v); else findAll(v, key, out); }
    return out;
}
const txt = (t) => (t == null ? null : typeof t === 'string' ? t : t.simpleText ?? t.content ?? (t.runs ? t.runs.map((r) => r.text).join('') : null));

const channels = new Map(); // channelId -> info
const linkSources = new Map(); // platform:key -> { link, foundVia:Set, keywords:Set }
function addLink(link, via, keyword) {
    const id = `${link.platform}:${link.key.toLowerCase()}`;
    if (!linkSources.has(id)) linkSources.set(id, { link, foundVia: new Set(), keywords: new Set() });
    const e = linkSources.get(id);
    if (via) e.foundVia.add(via);
    if (keyword) e.keywords.add(keyword);
}
function touchChannel(id, data, keyword) {
    if (!id) return null;
    const c = channels.get(id) ?? { channelId: id, keywords: new Set(), recentViews: 0, activeRecently: false };
    for (const [k, v] of Object.entries(data)) if (v != null && v !== '' && (c[k] == null || k === 'recentViews')) c[k] = v;
    if (keyword) c.keywords.add(keyword);
    channels.set(id, c);
    return c;
}

async function youtubeSearch(keyword) {
    // 1) channels matching the keyword
    const chHtml = await request(`https://www.youtube.com/results?search_query=${encodeURIComponent(keyword)}&sp=EgIQAg%253D%253D&hl=en&gl=${country}`);
    stats.youtubeSearches++;
    const chData = chHtml ? (grab(chHtml, 'var ytInitialData = ') ?? grab(chHtml, 'ytInitialData = ')) : null;
    let n = 0;
    for (const r of findAll(chData, 'channelRenderer')) {
        if (n >= maxChannelsPerKeyword) break;
        const texts = [txt(r.subscriberCountText), txt(r.videoCountText)].filter(Boolean);
        const subs = texts.find((t) => /subscri|suscript|inscrit/i.test(t));
        const handle = texts.find((t) => /^@/.test(t)) ?? null;
        touchChannel(r.channelId, { name: txt(r.title), handle, subscribers: parseCount(subs), description: txt(r.descriptionSnippet) }, keyword);
        n++;
    }
    // 2) videos uploaded this month: shows which channels are active, and their descriptions carry group links
    const vHtml = await request(`https://www.youtube.com/results?search_query=${encodeURIComponent(keyword)}&sp=EgIIBA%253D%253D&hl=en&gl=${country}`);
    stats.youtubeSearches++;
    const vData = vHtml ? (grab(vHtml, 'var ytInitialData = ') ?? grab(vHtml, 'ytInitialData = ')) : null;
    const videos = [];
    for (const v of findAll(vData, 'videoRenderer')) {
        const owner = v.ownerText ?? v.longBylineText;
        const chId = owner?.runs?.[0]?.navigationEndpoint?.browseEndpoint?.browseId;
        const views = parseCount(txt(v.viewCountText)) ?? 0;
        const c = touchChannel(chId, { name: txt(owner) }, keyword);
        if (c) { c.activeRecently = true; c.recentViews += views; }
        for (const l of extractCommunityLinks(txt(v.detailedMetadataSnippets?.[0]?.snippetText) ?? '')) addLink(l, `YouTube video ${v.videoId}`, keyword);
        videos.push({ id: v.videoId, views, chId });
    }
    videos.sort((a, b) => b.views - a.views);
    log.info(`"${keyword}": ${n} channels, ${videos.length} recent videos`);
    return videos.slice(0, videosToScanPerKeyword).map((v) => ({ ...v, keyword }));
}

async function scanVideo(v) {
    const html = await request(`https://www.youtube.com/watch?v=${v.id}&hl=en&gl=${country}`);
    stats.videosScanned++;
    if (!html) return;
    const p = grab(html, 'var ytInitialPlayerResponse = ') ?? grab(html, 'ytInitialPlayerResponse = ') ?? {};
    const desc = p.videoDetails?.shortDescription ?? '';
    const chName = p.videoDetails?.author ?? channels.get(v.chId)?.name ?? 'channel';
    for (const l of extractCommunityLinks(desc)) addLink(l, `YouTube: ${chName}`, v.keyword);
}

async function scanChannel(c) {
    const html = await request(`https://www.youtube.com/channel/${c.channelId}/about?hl=en&gl=${country}`);
    stats.youtubeChannelsScanned++;
    if (!html) return;
    const data = grab(html, 'var ytInitialData = ') ?? grab(html, 'ytInitialData = ');
    const meta = data?.metadata?.channelMetadataRenderer ?? {};
    const about = findAll(data, 'aboutChannelViewModel')[0] ?? {};
    const subsText = txt(about.subscriberCountText) ?? html.match(/"([\d.,]+[KMB]? subscribers)"/)?.[1];
    if (meta.title) c.name = meta.title;
    if (meta.description) c.description = meta.description;
    if (meta.vanityChannelUrl) c.url = meta.vanityChannelUrl.replace(/^http:/, 'https:');
    const subs = parseCount(subsText);
    if (subs != null) c.subscribers = subs;
    c.country = about.country ?? c.country ?? null;
    for (const l of extractCommunityLinks(html)) addLink(l, `YouTube: ${c.name ?? c.channelId}`, [...c.keywords][0]);
}

// ---------- Telegram / Discord / WhatsApp ----------
const results = new Map();
function finalize(base, sourceEntry) {
    const text = `${base.name ?? ''} ${base.description ?? ''}`;
    const rel = relevance(text, terms);
    const lang = detectLanguage(text);
    const item = {
        platform: base.platform,
        name: base.name ?? null,
        url: base.url,
        members: base.members ?? null,
        online: base.online ?? null,
        postsPerWeek: base.postsPerWeek ?? null,
        lastPostAt: base.lastPostAt ?? null,
        daysSinceLastPost: base.daysSinceLastPost ?? null,
        activeRecently: base.activeRecently ?? (base.daysSinceLastPost != null ? base.daysSinceLastPost <= 30 : null),
        language: lang,
        matchedTerms: rel.matched,
        description: base.description ? base.description.slice(0, 500) : null,
        foundVia: sourceEntry ? [...sourceEntry.foundVia].slice(0, 5) : [base.foundVia].filter(Boolean),
        keywords: sourceEntry ? [...sourceEntry.keywords] : (base.keywords ?? []),
        country: base.country ?? null,
        checkedAt: new Date().toISOString(),
    };
    item.score = scoreCommunity(item);
    // filters
    if (!includeUnrelated && rel.matched.length === 0 && (base.name || base.description)) { stats.skippedUnrelated++; return; }
    if (item.members != null && item.members < minMembers) { stats.skippedSmall++; return; }
    if (item.members == null && !includeUnknownSize) { stats.skippedSmall++; return; }
    if (item.daysSinceLastPost != null && maxDaysSinceLastPost > 0 && item.daysSinceLastPost > maxDaysSinceLastPost) { stats.skippedInactive++; return; }
    if (languages.length && lang && !languages.includes(lang)) { stats.skippedLanguage++; return; }
    results.set(item.url.toLowerCase(), item);
}

const tgSeen = new Set();
async function checkTelegram(name, depth, entry) {
    const key = name.toLowerCase();
    if (tgSeen.has(key) || tgSeen.size >= maxTelegramChannels) return [];
    tgSeen.add(key);
    stats.telegramChecked++;
    let html = await request(`https://t.me/s/${name}`);
    let info = parseTelegramPage(html);
    if (!info) { html = await request(`https://t.me/${name}`); info = parseTelegramPage(html); }
    if (!info) { stats.skippedNotCommunity++; return []; }
    finalize({ platform: info.kind === 'group' ? 'telegram-group' : 'telegram-channel', name: info.title, url: `https://t.me/${name}`, ...info }, entry);
    return depth > 0 ? info.related.map((r) => ({ name: r, depth: depth - 1, via: `Telegram: ${info.title}` })) : [];
}

async function checkDiscord(code, entry) {
    stats.discordChecked++;
    const json = await request(`https://discord.com/api/v9/invites/${encodeURIComponent(code)}?with_counts=true`, { json: true });
    const info = parseDiscordInvite(json);
    if (!info) { stats.skippedNotCommunity++; return; }
    finalize({ platform: 'discord', name: info.title, description: info.description, members: info.members, online: info.online, url: `https://discord.gg/${code}` }, entry);
}

async function checkWhatsApp(platform, code, url, entry) {
    stats.whatsappChecked++;
    const html = await request(url);
    const title = decodeHtml(html?.match(/<meta property="og:title" content="([^"]*)"/)?.[1] ?? '') || null;
    if (!title || /^WhatsApp/i.test(title)) { stats.skippedNotCommunity++; return; }
    const desc = decodeHtml(html.match(/<meta property="og:description" content="([^"]*)"/)?.[1] ?? '') || null;
    const followers = platform === 'whatsapp-channel' ? parseCount(desc?.match(/([\d.,KM]+)\s*followers/i)?.[1]) : null;
    finalize({ platform, name: title, description: desc, members: followers, url }, entry);
}

// ---------- run ----------
const scanQueue = [];
await pool(keywords, async (k) => { scanQueue.push(...await youtubeSearch(k)); });

const topChannels = [...channels.values()]
    .sort((a, b) => (b.subscribers ?? 0) - (a.subscribers ?? 0))
    .slice(0, Math.max(1, maxChannelsPerKeyword * Math.max(1, keywords.length)));
await pool(topChannels, scanChannel);
await pool(scanQueue, scanVideo);
log.info(`YouTube: ${channels.size} channels seen, ${linkSources.size} community links found.`);

if (includeYouTubeChannels) {
    for (const c of channels.values()) {
        if (c.subscribers == null) continue;
        finalize({
            platform: 'youtube', name: c.name, description: c.description, members: c.subscribers,
            url: c.url ?? `https://www.youtube.com/channel/${c.channelId}`, activeRecently: c.activeRecently,
            country: c.country, keywords: [...c.keywords], foundVia: 'YouTube search',
        });
    }
}

let tgQueue = seeds.map((s) => ({ name: s.replace(/^https?:\/\/(t|telegram)\.me\/(s\/)?/i, '').replace(/^@/, '').split(/[/?#]/)[0], depth: telegramDepth, via: 'Your list' }));
for (const e of linkSources.values()) if (e.link.platform === 'telegram') tgQueue.push({ name: e.link.key, depth: telegramDepth, entry: e });
while (tgQueue.length && tgSeen.size < maxTelegramChannels) {
    const batch = tgQueue; tgQueue = [];
    await pool(batch, async (t) => {
        const entry = t.entry ?? { foundVia: new Set([t.via]), keywords: new Set() };
        const more = await checkTelegram(t.name, t.depth, entry);
        tgQueue.push(...more.map((m) => ({ ...m, entry: { foundVia: new Set([m.via]), keywords: entry.keywords } })));
    });
}
const others = [...linkSources.values()].filter((e) => e.link.platform !== 'telegram');
await pool(others, async (e) => {
    const { platform, key, url } = e.link;
    if (platform === 'discord') return checkDiscord(key, e);
    if (platform === 'whatsapp' || platform === 'whatsapp-channel') return checkWhatsApp(platform, key, url, e);
    if (platform === 'telegram-private') finalize({ platform, name: null, url, description: null }, e);
});

const sorted = [...results.values()].sort((a, b) => b.score - a.score).slice(0, maxResults);
for (const item of sorted) await Actor.pushData(item, 'community');
const byPlatform = sorted.reduce((m, r) => { m[r.platform] = (m[r.platform] ?? 0) + 1; return m; }, {});
await Actor.setValue('SUMMARY', { communities: sorted.length, byPlatform, stats });
log.info(`Done: ${sorted.length} communities ${JSON.stringify(byPlatform)}. Stats: ${JSON.stringify(stats)}`);
await Actor.exit();

